export default {
    extends: ['@commitlint/config-conventional'],
    // Jira-style tags like "[ALL-1234]" or "[ALL-1234][ALL-5678]" are allowed
    // before the conventional "type(scope): subject" header — squash-merged
    // commits carry these from their PR titles.
    parserPreset: {
        parserOpts: {
            headerPattern: /^(?:\[[^\]]+\]\s*)*(\w*)(?:\((.*)\))?!?: (.*)$/,
            headerCorrespondence: ['type', 'scope', 'subject']
        }
    },
    // "Develop => Master (#123)" sync-PR titles have no conventional type —
    // they're generated by the sync workflow, not hand-authored commits.
    ignores: [(commit) => /^.+ => .+ \(#\d+\)$/.test(commit)],
    rules: {
        'header-max-length': [2, 'always', 100], // Enforce 100 char limit on header
        'subject-case': [0], // Allow any case in subject
        'scope-enum': [2, 'always', ['common', 'hazards', 'minerals', 'ccs', 'wetlands', 'wetlandplants', 'geophysics', 'subsurface', 'release', 'data-reviewer']],
        'footer-max-line-length': [1, 'always', 200],
        'body-max-line-length': [1, 'always', 200]
    }
};
